const timezone = $env.REPORT_TIMEZONE || 'America/Denver';

function localDateKey(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
  return `${map.year}-${map.month}-${map.day}`;
}

const now = new Date();
const reportDate = localDateKey(now, timezone);

return [{
  json: {
    report_timezone: timezone,
    report_date: reportDate,
    report_generated_at: now.toISOString()
  }
}];

const ctx = $('Code - Prepare Report Context').first().json;
const ordersResponse = $('HTTP - List Airtable Orders for Report Date').first()?.json || {};
const cloverResponse = $('HTTP - Get Clover Payments for Report').first()?.json || {};

const timezone = ctx.report_timezone || 'America/Denver';
const reportDate = ctx.report_date;
const generatedAt = ctx.report_generated_at;

const orders = Array.isArray(ordersResponse.records)
  ? ordersResponse.records.map(r => ({ airtable_record_id: r.id, ...(r.fields || {}) }))
  : [];

const allPayments = Array.isArray(cloverResponse.elements) ? cloverResponse.elements : [];

function localDateKey(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
  return `${map.year}-${map.month}-${map.day}`;
}

function localTime(dateLike, timeZone) {
  if (!dateLike) return '';
  const d = dateLike instanceof Date ? dateLike : new Date(dateLike);
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: 'numeric',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  }).format(d);
}

function money(value) {
  const num = Number(value || 0);
  return `$${num.toFixed(2)}`;
}

function parseItems(row) {
  try {
    const items = typeof row.items_json === 'string' ? JSON.parse(row.items_json) : [];
    return Array.isArray(items) ? items : [];
  } catch (e) {
    return [];
  }
}

function orderedNames(row) {
  const items = parseItems(row);
  const names = items
    .map((i) => String(i?.name || i?.nameTranslated?.en || '').trim())
    .filter(Boolean);
  return names.join(', ');
}

function productsSummary(row) {
  const candidates = [
    row.products_report,
    row.product_ids_report,
    row.products_summary,
    row.product_summary,
    row.products_display
  ].filter(Boolean);

  const linked = candidates.length
    ? (Array.isArray(candidates[0]) ? candidates[0].join(', ') : String(candidates[0]))
    : (Array.isArray(row.products) && row.products.length ? row.products.join(', ') : '');

  const ordered = orderedNames(row);

  if (linked && ordered) return `${linked} (ordered: ${ordered})`;
  if (linked) return linked;
  if (ordered) return `(not yet linked) ordered: ${ordered}`;
  return '(none linked)';
}

// Build Ecwid product tally from order line items
const tallyMap = new Map();
for (const row of orders) {
  const orderRef = String(row.order_code || row.ecwid_order_id || row.order_number || '(unknown)');
  for (const item of parseItems(row)) {
    const name = String(item?.name || item?.nameTranslated?.en || '(unknown product)').trim() || '(unknown product)';
    const sku = String(item?.sku || '').trim() || '';
    const productId = String(item?.productId || '').trim() || '';
    const qty = Number(item?.quantity || 0) || 0;
    const key = `${name}|||${sku}|||${productId}`;

    if (!tallyMap.has(key)) {
      tallyMap.set(key, {
        name,
        sku,
        productId,
        qty: 0,
        orderRefs: new Set(),
      });
    }

    const entry = tallyMap.get(key);
    entry.qty += qty;
    entry.orderRefs.add(orderRef);
  }
}

const productTally = Array.from(tallyMap.values()).sort((a, b) => {
  const qtyDiff = b.qty - a.qty;
  if (qtyDiff !== 0) return qtyDiff;
  return a.name.localeCompare(b.name);
});

const todaysPayments = allPayments.filter((p) => {
  const created = Number(p.createdTime || 0);
  if (!created) return false;
  return localDateKey(new Date(created), timezone) === reportDate;
});

const successfulPayments = todaysPayments.filter((p) => String(p.result || '') === 'SUCCESS');

const reconciledOrders = orders.filter((r) => String(r.clover_reconciliation_status || '') === 'reconciled');
const pendingOrders = orders.filter((r) => String(r.clover_reconciliation_status || '') === 'pending');
const reviewOrders = orders.filter((r) => String(r.clover_reconciliation_status || '') === 'needs_review');
const otherOrders = orders.filter((r) => !['reconciled', 'pending', 'needs_review'].includes(String(r.clover_reconciliation_status || '')));

const usedPaymentIds = new Set(
  reconciledOrders.map((r) => String(r.clover_payment_id || '').trim()).filter(Boolean)
);

const unreconciledPayments = successfulPayments.filter((p) => !usedPaymentIds.has(String(p.id || '').trim()));

const lines = [];
lines.push(`MushroomProcess Daily Reconciliation Report`);
lines.push(`Report date: ${reportDate} (${timezone})`);
lines.push(`Generated at: ${generatedAt}`);
lines.push('');
lines.push(`Summary`);
lines.push(`- Airtable orders today: ${orders.length}`);
lines.push(`- Reconciled orders: ${reconciledOrders.length}`);
lines.push(`- Pending orders: ${pendingOrders.length}`);
lines.push(`- Needs review orders: ${reviewOrders.length}`);
lines.push(`- Other order statuses: ${otherOrders.length}`);
lines.push(`- Clover SUCCESS payments today: ${successfulPayments.length}`);
lines.push(`- Clover payments not tied to reconciled orders: ${unreconciledPayments.length}`);
lines.push(`- Distinct Ecwid products sold today: ${productTally.length}`);
lines.push('');

lines.push(`Ecwid Product Tally`);
if (!productTally.length) {
  lines.push(`(none)`);
} else {
  productTally.forEach((p) => {
    const skuPart = p.sku ? ` | SKU ${p.sku}` : '';
    const productIdPart = p.productId ? ` | productId ${p.productId}` : '';
    const ordersPart = Array.from(p.orderRefs).sort().join(', ');
    lines.push(
      `- ${p.name} | qty ${p.qty}${skuPart}${productIdPart} | orders: ${ordersPart || '(none)'}`
    );
  });
}
lines.push('');

lines.push(`Reconciled Orders`);
if (!reconciledOrders.length) {
  lines.push(`(none)`);
} else {
  reconciledOrders.forEach((r) => {
    lines.push(
      `- Ecwid ${r.order_code || r.ecwid_order_id || r.order_number || '(unknown)'} | ` +
      `${money(r.order_total)} | ordered ${localTime(r.order_date, timezone)} | ` +
      `paid ${localTime(r.clover_payment_time, timezone)} | ` +
      `Clover ${r.clover_payment_id || '(none)'} | ` +
      `Products: ${productsSummary(r)}`
    );
  });
}
lines.push('');

lines.push(`Ecwid Orders Not Reconciled`);
const unreconciledOrders = [...pendingOrders, ...reviewOrders, ...otherOrders];
if (!unreconciledOrders.length) {
  lines.push(`(none)`);
} else {
  unreconciledOrders.forEach((r) => {
    lines.push(
      `- Ecwid ${r.order_code || r.ecwid_order_id || r.order_number || '(unknown)'} | ` +
      `${money(r.order_total)} | ordered ${localTime(r.order_date, timezone)} | ` +
      `status ${r.clover_reconciliation_status || '(blank)'} | ` +
      `Products: ${productsSummary(r)} | ` +
      `Notes: ${r.reconciliation_notes || '(none)'}`
    );
  });
}
lines.push('');

lines.push(`Clover Payments Not Reconciled To Ecwid Orders`);
if (!unreconciledPayments.length) {
  lines.push(`(none)`);
} else {
  unreconciledPayments.forEach((p) => {
    lines.push(
      `- Clover ${p.id || '(unknown)'} | ` +
      `${money((Number(p.amount || 0)) / 100)} | ` +
      `paid ${localTime(new Date(Number(p.createdTime || 0)), timezone)} | ` +
      `Clover order ${p.order?.id || '(none)'} | ` +
      `external ref ${p.externalReferenceId || '(none)'}`
    );
  });
}

const reportText = lines.join('\n');

return [{
  json: {
    report_date: reportDate,
    report_timezone: timezone,
    report_generated_at: generatedAt,
    orders_count: orders.length,
    reconciled_orders_count: reconciledOrders.length,
    unreconciled_orders_count: unreconciledOrders.length,
    successful_clover_payments_count: successfulPayments.length,
    unreconciled_clover_payments_count: unreconciledPayments.length,
    product_tally_count: productTally.length,
    report_text: reportText
  }
}];

const row = $json;
const reportText = String(row.report_text || '');
const reportDate = String(row.report_date || new Date().toISOString().slice(0,10));

function escapePdfText(s) {
  return String(s)
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)');
}

function wrapLine(line, maxLen) {
  if (line.length <= maxLen) return [line];
  const words = line.split(/\s+/);
  const out = [];
  let cur = '';
  for (const word of words) {
    const next = cur ? `${cur} ${word}` : word;
    if (next.length <= maxLen) {
      cur = next;
    } else {
      if (cur) out.push(cur);
      if (word.length > maxLen) {
        for (let i = 0; i < word.length; i += maxLen) out.push(word.slice(i, i + maxLen));
        cur = '';
      } else {
        cur = word;
      }
    }
  }
  if (cur) out.push(cur);
  return out;
}

function makePdfFromText(text) {
  const rawLines = String(text).replace(/\r/g, '').split('\n');
  const wrapped = [];
  for (const line of rawLines) {
    const normalized = line === '' ? ' ' : line;
    wrapped.push(...wrapLine(normalized, 95));
  }

  const linesPerPage = 48;
  const pages = [];
  for (let i = 0; i < wrapped.length; i += linesPerPage) {
    pages.push(wrapped.slice(i, i + linesPerPage));
  }
  if (!pages.length) pages.push([' ']);

  const objects = [];
  const addObject = (content) => {
    objects.push(content);
    return objects.length;
  };

  const fontId = addObject('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  const pageIds = [];
  const contentIds = [];

  for (const pageLines of pages) {
    let y = 770;
    const content = ['BT', '/F1 10 Tf', '14 TL', '50 770 Td'];
    pageLines.forEach((line, idx) => {
      if (idx === 0) {
        content.push(`(${escapePdfText(line)}) Tj`);
      } else {
        content.push('T*');
        content.push(`(${escapePdfText(line)}) Tj`);
      }
    });
    content.push('ET');
    const stream = content.join('\n');
    const contentId = addObject(`<< /Length ${Buffer.byteLength(stream, 'utf8')} >>\nstream\n${stream}\nendstream`);
    contentIds.push(contentId);
    const pageId = addObject(`<< /Type /Page /Parent PAGES_ID 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`);
    pageIds.push(pageId);
  }

  const kids = pageIds.map(id => `${id} 0 R`).join(' ');
  const pagesId = addObject(`<< /Type /Pages /Kids [${kids}] /Count ${pageIds.length} >>`);
  for (const pageId of pageIds) {
    objects[pageId - 1] = objects[pageId - 1].replace('PAGES_ID', String(pagesId));
  }
  const catalogId = addObject(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);

  let pdf = '%PDF-1.4\n';
  const offsets = [0];
  for (let i = 0; i < objects.length; i++) {
    offsets.push(Buffer.byteLength(pdf, 'utf8'));
    pdf += `${i + 1} 0 obj\n${objects[i]}\nendobj\n`;
  }
  const xrefOffset = Buffer.byteLength(pdf, 'utf8');
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += '0000000000 65535 f \n';
  for (let i = 1; i <= objects.length; i++) {
    pdf += `${String(offsets[i]).padStart(10, '0')} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root ${catalogId} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
  return Buffer.from(pdf, 'utf8');
}

const pdfBuffer = makePdfFromText(reportText);
return [{
  json: {
    ...row,
    pdf_filename: `mushroomprocess-reconciliation-${reportDate}.pdf`
  },
  binary: {
    pdf: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: `mushroomprocess-reconciliation-${reportDate}.pdf`
    }
  }
}];
